<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue';import {onBeforeRouteLeave} from 'vue-router';
import {api,apiMessage} from '@/api/client';import {requiresConnection} from '@/connectionState';
import {runtimeFields,validRuntime,runtimeDiff,type RuntimeLimits,type RuntimePolicy,type RuntimeAudit} from '@/adminCenter';
const policy=ref<RuntimePolicy|null>(null),draft=reactive<RuntimeLimits>({maxConcurrent:1,queueCapacity:0,maxInputChars:16000,maxOutputTokens:4096,totalOutputTokens:8192,timeoutSeconds:60});
const busy=ref(false),error=ref(''),notice=ref(''),preview=ref(false),confirmed=ref(false),audit=ref<{items:RuntimeAudit[];page:number;size:number;total:number}|null>(null),restore=ref<RuntimeAudit|null>(null);
const dirty=computed(()=>!!policy.value&&JSON.stringify(draft)!==JSON.stringify(policy.value.limits));
const differences=computed(()=>policy.value?runtimeDiff(policy.value.limits,restore.value?.before.limits??draft):[]);
watch(()=>JSON.stringify(draft),()=>{preview.value=false;confirmed.value=false;restore.value=null;});
async function history(page=0){audit.value=(await api.get('/admin/ai/runtime/audit',{params:{page,size:10}})).data;}
async function moveHistory(page:number){if(busy.value||requiresConnection())return;busy.value=true;error.value='';try{await history(page);}catch(e){error.value=apiMessage(e);}finally{busy.value=false;}}
async function load(){if(busy.value||dirty.value&&!confirm('读取最新配置会丢弃本页尚未保存的参数，确定继续？'))return;busy.value=true;error.value='';try{const next=(await api.get<RuntimePolicy>('/admin/ai/runtime')).data;policy.value=next;Object.assign(draft,next.limits);preview.value=false;restore.value=null;confirmed.value=false;await history();}catch(e){error.value=apiMessage(e);}finally{busy.value=false;}}
function prepare(){if(!validRuntime(draft)){error.value='请填写范围内的整数；合计输出不能小于首轮，也不能超过首轮的两倍或8192。';return;}restore.value=null;preview.value=true;confirmed.value=false;error.value='';}
function prepareRestore(row:RuntimeAudit){restore.value=row;preview.value=true;confirmed.value=false;error.value='';}
async function save(){if(!policy.value||busy.value||!preview.value||!confirmed.value||requiresConnection())return;busy.value=true;error.value='';notice.value='';try{const next=restore.value?(await api.post<RuntimePolicy>(`/admin/ai/runtime/restore/${restore.value.id}`,{version:policy.value.version,confirmed:true})).data:(await api.put<RuntimePolicy>('/admin/ai/runtime',{limits:{...draft},version:policy.value.version})).data;policy.value=next;Object.assign(draft,next.limits);preview.value=false;restore.value=null;confirmed.value=false;notice.value='配置已保存。新准入与调度使用最新值；已接收请求保留原输入/输出/超时快照，降低容量只排空，不中断或重放。';await history();}catch(e){error.value=apiMessage(e)+' 当前输入保留；请读取最新配置、重新核对后再提交。';preview.value=false;confirmed.value=false;}finally{busy.value=false;}}
function leave(){return !busy.value&&(!dirty.value&&!preview.value||confirm('运行参数尚未保存，确定离开？'));}onBeforeRouteLeave(leave);
function unload(e:BeforeUnloadEvent){if(dirty.value||busy.value){e.preventDefault();e.returnValue='';}}
onMounted(()=>{void load();window.addEventListener('beforeunload',unload);});onUnmounted(()=>window.removeEventListener('beforeunload',unload));
</script>
<template><section class="section runtime-panel" aria-labelledby="runtime-title"><header class="section-title"><div><h2 id="runtime-title">AI运行策略</h2><p>单实例、小服务器的有界配置；不修改密钥、上游地址或模型。</p></div><button class="btn" :disabled="busy||requiresConnection()" @click="load">读取最新运行配置</button></header><div class="runtime-body"><p v-if="error" class="error-text" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="requiresConnection()" role="status">管理配置需要联网，不进入离线自动重放。</p><template v-if="policy"><p>配置版本 {{policy.version}} · {{policy.updatedAt?`保存于 ${new Date(policy.updatedAt).toLocaleString('zh-CN')}`:'尚未保存覆盖，沿用部署初始参数'}}</p><p class="helper-text">并发1–2，等待0–8；上下文100–32000字，输出首轮及合计最多8192 Token，合计超时1–120秒。消息仍最多8000字。上下文还有64K保守输入字节边界，不能将字符上限当成任意大小保证。</p>
<form @submit.prevent="prepare"><fieldset :disabled="busy||requiresConnection()"><label v-for="field in runtimeFields" :key="field.key">{{field.label}}<input v-model.number="draft[field.key]" type="number" :min="field.min" :max="field.max" step="1" required inputmode="numeric"/></label></fieldset><button class="btn primary" :disabled="busy||!dirty||requiresConnection()">预览参数修改</button></form>
<section v-if="preview" class="runtime-preview" aria-label="运行配置差异"><h3>{{restore?'恢复这条审计的修改前参数':'核对运行参数变化'}}</h3><p v-if="!differences.length">数值未变化，仍会记录一次明确确认的恢复操作。</p><ul><li v-for="d in differences" :key="d.label">{{d.label}}：{{d.before}} → {{d.after}}</li></ul><p>不会终止已运行请求、丢弃已排队请求或清零每日次数。恢复同样生成新版本和审计，不重新调用AI。</p><label class="runtime-check"><input v-model="confirmed" type="checkbox"/>我已核对参数变化及生效范围</label><button class="btn primary" :disabled="busy||!confirmed||requiresConnection()" @click="save">确认保存运行配置</button></section>
<h3>运行配置审计</h3><p v-if="!audit?.items.length">尚无运行参数修改记录。</p><ol class="runtime-audit"><li v-for="row in audit?.items" :key="row.id"><strong>{{row.actor}} · 版本 {{row.before.version}} → {{row.after.version}}</strong><time>{{new Date(row.createdAt).toLocaleString('zh-CN')}}</time><ul><li v-for="d in runtimeDiff(row.before.limits,row.after.limits)" :key="d.label">{{d.label}}：{{d.before}} → {{d.after}}</li></ul><p v-if="row.restoredFrom">恢复自审计 {{row.restoredFrom}}</p><button class="btn" :disabled="busy||dirty||requiresConnection()" @click="prepareRestore(row)">预览恢复修改前参数</button></li></ol>
<nav v-if="audit" class="button-row" aria-label="运行配置审计分页"><span>共 {{audit.total}} 项 · 第 {{audit.page+1}} 页</span><button class="btn" :disabled="busy||audit.page===0" @click="moveHistory(audit.page-1)">上一页</button><button class="btn" :disabled="busy||(audit.page+1)*audit.size>=audit.total" @click="moveHistory(audit.page+1)">下一页</button></nav></template></div></section></template>
<style scoped>.runtime-panel{min-width:0}.section-title p{font-size:.85rem;margin:8px 0 0;color:var(--muted)}.runtime-body{padding:22px;min-width:0}.runtime-body p{line-height:1.8}.runtime-body fieldset{border:0;margin:0 0 20px;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;min-width:0}.runtime-body label{display:grid;gap:10px;font-size:.85rem}.runtime-body input:not([type=checkbox]){width:100%;min-width:0}.runtime-body .btn{min-height:44px}.runtime-preview{padding:20px;border:1px solid var(--blue);background:#f7f7f8;margin:24px 0}.runtime-preview .runtime-check{display:flex;gap:10px;align-items:center;margin:18px 0}.runtime-check input{width:20px;height:20px;flex:0 0 20px}.runtime-audit{list-style:none;padding:0}.runtime-audit>li{border-top:1px solid var(--line);padding:20px 0;overflow-wrap:anywhere}.runtime-audit time{display:block;font-size:.8rem;color:var(--muted);margin-top:8px}.runtime-audit ul{padding-left:20px;font-size:.85rem;line-height:1.8}.runtime-audit p{font-size:.8rem}.runtime-body>h3{margin-top:28px}@media(max-width:700px){.runtime-body{padding:16px}.runtime-body fieldset{grid-template-columns:1fr}.section-title{flex-wrap:wrap}.runtime-preview{padding:16px}}</style>
